<?php
namespace Tests\Feature\Seller;
use App\Models\{BusinessEntity,PlatformAdmin,Store,StoreUser,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class StoreApprovalWorkflowTest extends TestCase {use RefreshDatabase; private function storeFor(User $u):Store{$b=BusinessEntity::create(['type'=>'personal_business','legal_name'=>'Test','country_code'=>'AE','phone'=>'1','email'=>'b@example.com','status'=>'active']);$b->users()->attach($u->id,['role'=>'owner','is_primary_owner'=>true]);$s=Store::create(['business_entity_id'=>$b->id,'name'=>'Test Store','slug'=>'test-store','country_code'=>'AE','phone'=>'1','email'=>'s@example.com','status'=>'draft']);StoreUser::create(['store_id'=>$s->id,'user_id'=>$u->id,'role'=>'owner','is_primary_owner'=>true]);return $s;}
 public function test_seller_can_submit_and_withdraw_pending_store():void{$u=User::factory()->create();$s=$this->storeFor($u);$this->actingAs($u)->post("/seller/stores/{$s->id}/submit")->assertRedirect();$this->assertDatabaseHas('stores',['id'=>$s->id,'status'=>'pending']);$this->actingAs($u)->post("/seller/stores/{$s->id}/withdraw")->assertRedirect();$this->assertDatabaseHas('stores',['id'=>$s->id,'status'=>'draft']);}
 public function test_admin_can_review_and_request_changes():void{$seller=User::factory()->create();$admin=User::factory()->create();PlatformAdmin::create(['user_id'=>$admin->id,'is_super_admin'=>true,'status'=>'active']);$s=$this->storeFor($seller);$s->update(['status'=>'pending']);$this->actingAs($admin)->post("/admin/stores/{$s->id}/start-review")->assertRedirect();$this->actingAs($admin)->post("/admin/stores/{$s->id}/needs-changes",['note'=>'Please correct the address.'])->assertRedirect();$this->assertDatabaseHas('stores',['id'=>$s->id,'status'=>'needs_changes']);$this->assertDatabaseHas('store_status_histories',['store_id'=>$s->id,'to_status'=>'needs_changes','note'=>'Please correct the address.']);}
 public function test_non_admin_cannot_open_admin_store_queue():void{$u=User::factory()->create();$this->actingAs($u)->get('/admin/stores')->assertForbidden();}
}
